import math

def cos(a, b):
    return sum(x * y for x, y in zip(a, b)) / (sum(x * x for x in a) ** 0.5 * sum(y * y for y in b) ** 0.5)

# toy embeddings (real ones come from a model; geometry is the point)
caps = {
    'summarizer': [0.9, 0.1, 0.2],
    'translator': [0.1, 0.9, 0.2],
    'calculator': [0.1, 0.2, 0.9],
}
task = [0.85, 0.15, 0.25]  # 'summarize this contract'
ranked = sorted(caps.items(), key=lambda kv: cos(task, kv[1]), reverse=True)
for name, v in ranked:
    print('%-12s similarity %.3f' % (name, cos(task, v)))
print('new capability? write its description -> instantly routable, zero training')

registry = {}

def register(name, description, cost, latency_ms):
    registry[name] = {'desc': description, 'cost': cost, 'latency': latency_ms, 'v': 1}

def deregister(name):
    del registry[name]

register('summarizer', 'condenses long documents to key points', 0.002, 800)
register('translator', 'translates between 40 languages', 0.001, 500)
print('registered:', sorted(registry))
print('summarizer:', registry['summarizer'])
print('honest metadata (cost, latency) lets the router trade off, not just match')

# prompt-based routing: the LLM chooses AND explains (simulated decision logic)
caps = {
    'fast-summarizer': {'speed': 9, 'care': 3},
    'careful-summarizer': {'speed': 3, 'care': 9},
}

def route(task):
    # the 'LLM' reads nuance: 'legal contract' needs care over speed
    careful = any(w in task.lower() for w in ('legal', 'contract', 'medical'))
    choice = 'careful-summarizer' if careful else 'fast-summarizer'
    return choice, 'task mentions high-stakes domain -> care over speed'

for t in ('summarize this blog post', 'summarize this legal contract'):
    c, why = route(t)
    print('%-32s -> %s (%s)' % (t, c, why))

